def scatter_florets(mode_cfg):
    """Instance florets on a core sphere surface."""
    n_seg = 18
    n_ring = 17
    core_r = 0.043618
    core_warp = (1.0099, 1.0962, 0.65225)
    bpy.ops.mesh.primitive_uv_sphere_add(segments=n_seg, ring_count=n_ring,
                                         radius=core_r, location=(0, 0, 0))
    core = bpy.context.active_object
    core.scale = core_warp
    apply_xform(core)
    core.data.update()
    pts = [np.array(f.center) for f in core.data.polygons]
    norms = [np.array(f.normal) for f in core.data.polygons]
    keep = mode_cfg["random_dropout"]
    rh, rl = mode_cfg["row_less_than"], mode_cfg["row_great_than"]
    ch_val, cl_val = mode_cfg["col_less_than"], mode_cfg["col_great_than"]
    valid_ids = []
    for fi in range(len(pts)):
        if np.random.uniform(0, 1) > keep:
            continue
        row, col = fi // n_seg, fi % n_seg
        if not ((row < rh * n_ring) and (row > rl * n_ring) and (col < ch_val * n_seg) and (col > cl_val * n_seg)):
            valid_ids.append(fi)
    proto = craft_floret()
    if proto is None:
        return core
    assembly = [core]
    for fi in valid_ids:
        n = norms[fi]
        nl = np.linalg.norm(n)
        if nl < 1e-6:
            continue
        n /= nl
        sz = float(np.random.uniform(0.4, 0.7))
        inst = proto.copy()
        inst.data = proto.data.copy()
        bpy.context.scene.collection.objects.link(inst)
        inst.scale = (sz, sz, sz)
        apply_xform(inst)
        z = np.array([0, 0, 1], dtype=float)
        ax = np.cross(z, n)
        al = np.linalg.norm(ax)
        d = np.dot(z, n)
        if al > 1e-6:
            ax /= al
            inst.matrix_world = Matrix.Rotation(math.acos(np.clip(d, -1, 1)), 4, Vector(ax)) @ inst.matrix_world
        elif d < 0:
            inst.rotation_euler.x = math.pi
        inst.location = Vector(pts[fi])
        apply_xform(inst)
        assembly.append(inst)
    kill_object(proto)
    return join_meshes(assembly)

def get_mode_cfg(mode):
    if mode == "full_flower":
        return {"random_dropout": 0.71699, "row_less_than": 0.0, "row_great_than": 0.0,
                "col_less_than": 0.0, "col_great_than": 0.0}
    elif mode == "no_flower":
        return {"random_dropout": 0.0, "row_less_than": 1.0, "row_great_than": 0.0,
                "col_less_than": 1.0, "col_great_than": 0.0}
    elif mode == "top_half_flower":
        return {"random_dropout": 0.0, "row_less_than": 0.0, "row_great_than": 0.0,
                "col_less_than": 1.0, "col_great_than": 0.0}
    elif mode == "top_missing_flower":
        return {"random_dropout": 0.0, "row_less_than": 1.0, "row_great_than": 0.0,
                "col_less_than": 0.0, "col_great_than": 0.0}
    elif mode == "sparse_flower":
        return {"random_dropout": 0.34561, "row_less_than": 0.0, "row_great_than": 0.0,
                "col_less_than": 0.0, "col_great_than": 0.0}
    else:
        raise ValueError(f"Unknown mode: {mode}")

def make_dandelion():
    """Complete dandelion: scape plus floret-covered head."""
    prep_scene()
    mode = 'sparse_flower'
    scape_w = 0.012812
    scape_obj, scape_top = build_scape(scape_w)
    components = [scape_obj]
    if mode != "no_flower":
        head = scatter_florets(get_mode_cfg(mode))
        if head is not None:
            flip = -0.20229
            head.scale = (flip, flip, flip)
            apply_xform(head)
            head.location = Vector(scape_top)
            apply_xform(head)
            components.append(head)
    plant = join_meshes(components)
    plant.location.z = 0
    apply_xform(plant)
    plant.name = "DandelionFactory"
    return plant

