def on(o):
    bpy.ops.object.select_all(action='DESELECT'); o.select_set(True); bpy.context.view_layer.objects.active=o

def tr(o, loc=False):
    on(o); bpy.ops.object.transform_apply(location=loc, rotation=True, scale=True)

def mx(o, t, apply=True, **kw):
    on(o); m=o.modifiers.new(name=t, type=t)
    for k,val in kw.items(): setattr(m,k,val)
    if apply: bpy.ops.object.modifier_apply(modifier=m.name)

def clr():
    bpy.ops.object.select_all(action='SELECT'); bpy.ops.object.delete()
    for m in list(bpy.data.meshes): bpy.data.meshes.remove(m)
    for c in list(bpy.data.curves): bpy.data.curves.remove(c)
    bpy.context.scene.cursor.location=(0,0,0)

def vc(o, arr): o.data.vertices.foreach_set('co', arr.reshape(-1))

def sm(o, lv, simple=False):
    if lv>0: mx(o,'SUBSURF',levels=lv,render_levels=lv,subdivision_type='SIMPLE' if simple else 'CATMULL_CLARK')

def gd(xn=10, yn=10):
    bpy.ops.mesh.primitive_grid_add(location=(0,0,0), x_subdivisions=xn, y_subdivisions=yn)
    o=bpy.context.active_object; tr(o, loc=True); return o

def tp(o, eo, bw):
    on(o); bpy.ops.object.mode_set(mode='EDIT')
    bm=bmesh.from_edit_mesh(o.data)
    for e in bm.edges:
        u,w=e.verts; x0,y0,_=u.co; x1,y1,_=w.co
        if x0>=0 and x1>=0 and abs(x0-x1)<2e-4:
            if y0>eo*bw and y1>eo*bw:
                bmesh.ops.pointmerge(bm, verts=[u,w], merge_co=(u.co+w.co)/2)
    bmesh.update_edit_mesh(o.data)
    bpy.ops.mesh.select_mode(type='EDGE'); bpy.ops.mesh.select_loose(extend=False)
    bpy.ops.mesh.delete(type='EDGE'); bpy.ops.object.mode_set(mode='OBJECT')

def run():
    W=0.5; hr=0.5538159587162458; bw=0.1744460331319738; gw=bw*0.30283417958917386; eo=0.2
    xa=np.array([W, -0.14797015451005982 * W, 0.3856371437920405*W, 1e-3,0,-1e-3,-2e-3, -W*hr+1e-3, -W*hr])
    ya=np.array([1e-3, bw*0.7979081961959794, bw,bw,bw, gw,gw,gw,gw])
    ii=[0]+list(range(len(xa))); xa=xa[ii]; xa[0]+=1e-3; ya=ya[ii]; ya[1]+=3e-3
    n=len(xa); o=gd(xn=n-1,yn=1)
    x=np.concatenate([xa]*2); y=np.concatenate([ya,np.zeros_like(ya)]); y[0::n]+=eo*bw
    y[1::n]+=eo*bw; y[2::n]+=eo*(bw-ya[2])
    z=np.concatenate([np.zeros_like(xa)]*2); vc(o, np.stack([x,y,z],-1))
    mx(o,'SOLIDIFY',thickness=0.02494657622011532); tp(o,eo,bw)
    sm(o,1); sm(o,1); sm(o,1,True)
    o.scale=[0.24715284479668156]*3; tr(o); return o

clr()

run()

class LargeShelfFactory(LargeShelfBaseFactory):
    def sample_params(self):
        params = dict()
        params["Dimensions"] = (
            uniform(0.25, 0.35),
            uniform(0.3, 2.0),
            uniform(0.9, 2.0),
        )
        params["bottom_board_height"] = 0.083
        params["shelf_depth"] = params["Dimensions"][0] - 0.01
        num_h = int((params["Dimensions"][2] - 0.083) / 0.3)
        params["shelf_cell_height"] = [
            (params["Dimensions"][2] - 0.083) / num_h for _ in range(num_h)
        ]
        num_v = max(int(params["Dimensions"][1] / 0.5), 1)
        params["shelf_cell_width"] = [
            params["Dimensions"][1] / num_v for _ in range(num_v)
        ]
        return params

